/// Reconstructs a `CanF64` from verified compile-time IEEE-754 bits on stack.
///
/// Safety & Traceability: Realises: [REQ-15], [FLS: fls_functions].
///
/// Contract: Preconditions: `bits` encodes a finite canonical `f64`;
/// Postconditions: returns exact `CanF64` or `CanF64::ZERO` fallback.
///
/// Bounds & Faults: Constant-time `const fn`; zero heap allocation or panics.
#[must_use]
pub const fn can_from_bits(bits: u64) -> CanF64 {
    match CanF64::try_new(f64::from_bits(bits)) {
        Ok(val) => val,
        Err(_) => CanF64::ZERO,
    }
}
