/// Guarded trigger events for `CompiledLifecycleFsm` transitions.
///
/// Safety & Traceability: Realises: [REQ-15], [FLS: fls_enumerations].
///
/// Contract: Preconditions: none; Postconditions: closed 4-event trigger set.
///
/// Bounds & Faults: 1-byte `Copy + Eq` value enum; zero heap state.
#[repr(u8)]
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CompiledLifecycleEvent {
    /// Self-test passed (`Init -> Nom`).
    CompleteInit = 0,
    /// Margin degradation detected (`Nom -> Deg`).
    Degrade = 1,
    /// Fault trip into latched `SafeHold` (`* -> SafeHold`).
    TripSafeHold = 2,
    /// Authorized supervisory recovery (`SafeHold -> Init`).
    SupervisoryReset = 3,
}
/// Zero-heap operational lifecycle automaton verified by Pass 0 (`C7`).
///
/// Safety & Traceability: Realises: [REQ-15], [REQ-23], [FLS: fls_structs].
///
/// Contract: Preconditions: starts in `LifecycleMode::Init`; Postconditions:
/// enforces latched `SafeHold` until `SupervisoryReset` (`DEAP_E0326`).
///
/// Bounds & Faults: 1-byte stack footprint; uncommanded steps fail closed.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CompiledLifecycleFsm {
    /// Active lifecycle mode.
    pub mode: LifecycleMode,
}
impl CompiledLifecycleFsm {
    /// Creates a `CompiledLifecycleFsm` initialized to `LifecycleMode::Init`.
    ///
    /// Safety & Traceability: Realises: [REQ-15], [FLS: fls_functions].
    ///
    /// Contract: Preconditions: none; Postconditions: `mode == Init`.
    ///
    /// Bounds & Faults: Constant-time `const fn`; zero heap allocation.
    #[must_use]
    pub const fn new() -> Self {
        let mode = LifecycleMode::Init;
        Self { mode }
    }
}
impl Default for CompiledLifecycleFsm {
    /// Returns `CompiledLifecycleFsm::new()`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn default() -> Self {
        Self::new()
    }
}
impl SafeHoldFsm for CompiledLifecycleFsm {
    type State = LifecycleMode;
    type Event = CompiledLifecycleEvent;
    /// Returns the active `LifecycleMode`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn current_state(&self) -> Self::State {
        self.mode
    }
    /// Returns `true` iff `state == LifecycleMode::SafeHold`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn is_safe_hold(state: Self::State) -> bool {
        state.is_safe_hold()
    }
    /// Applies one guarded transition or fails with `PreStpaCriterionFailedC7`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn step(&mut self, event: Self::Event) -> Result<Self::State, ErrorCode> {
        use CompiledLifecycleEvent as Ev;
        use LifecycleMode as Mode;
        let next = match (self.mode, event) {
            (Mode::Init, Ev::CompleteInit) => Mode::Nom,
            (Mode::Nom, Ev::Degrade) => Mode::Deg,
            (_, Ev::TripSafeHold) => Mode::SafeHold,
            (Mode::SafeHold, Ev::SupervisoryReset) => Mode::Init,
            _ => return Err(ErrorCode::PreStpaCriterionFailedC7),
        };
        self.mode = next;
        Ok(next)
    }
    /// Verifies universal `SafeHold` reachability across all 4 modes.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn verify_safe_hold_reachable() -> bool {
        let mut idx: usize = 0;
        while idx < LifecycleMode::ALL.len() {
            if let Some(&mode) = LifecycleMode::ALL.get(idx) {
                let mut probe = Self { mode };
                if !matches!(
                    probe.step(CompiledLifecycleEvent::TripSafeHold),
                    Ok(LifecycleMode::SafeHold)
                ) {
                    return false;
                }
            }
            idx = idx.saturating_add(1);
        }
        true
    }
}
