///
/// Bounds & Faults: Constant stack evaluation; returns `DEAP_E0326` if unreachable.
pub fn check_compiled_fsm_reachability() -> Result<(), ErrorCode> {
    verify_fsm_reachability::<CompiledLifecycleFsm>()
}
