#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct CompiledSignalEnvelope {
    /// Canonical signal identifier (`SIG-xx`).
    pub sig_id: &'static str,
    /// Lower inclusive bound IEEE-754 bits.
    pub min_bits: u64,
    /// Upper inclusive bound IEEE-754 bits.
    pub max_bits: u64,
    /// Sampled or fail-safe default value IEEE-754 bits.
    pub sample_bits: u64,
}
impl IsqBound for CompiledSignalEnvelope {
    /// Returns `sample_bits` as a coherent `PhysicalQuantity`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn quantity(&self) -> PhysicalQuantity {
        PhysicalQuantity::dimensionless(can_from_bits(self.sample_bits))
    }
    /// Returns `[min_bits, max_bits]` as a `ClosedInterval`.
    /// Realises: [REQ-15], [FLS: fls_traits].
    fn bounds(&self) -> ClosedInterval {
        ClosedInterval {
            min: can_from_bits(self.min_bits),
            max: can_from_bits(self.max_bits),
            dim: DimVec::NONE,
            info: InfoUnit::NONE,
        }
    }
}
